<template>
  <section class="main-view">
    <header class="view-header">
      <div><p class="eyebrow">LU NU MUSIC / PERSONAL LIBRARY</p><h1 v-if="!onlyLiked">Những giai điệu<br /><em>của riêng bạn.</em></h1><h1 v-else>Những bài hát<br /><em>được yêu thích.</em></h1><p class="lede">{{ onlyLiked ? 'Những ca khúc bạn đã đánh dấu, được giữ lại trong một không gian riêng tư trên thiết bị này.' : 'Một không gian nghe nhạc tinh gọn, sâu lắng và được thiết kế để bạn ở lại lâu hơn.' }}</p></div>
      <div class="header-actions"><button class="ghost-btn" @click="state.queueVisible = true">☷ <span>Hàng đợi</span></button><button class="primary-btn" :disabled="!filteredSongs.length" @click="playAll">▶ Phát tất cả</button></div>
    </header>

    <div class="stats-row"><div><span class="stat-value">{{ songs.length }}</span><span class="stat-label">BÀI HÁT</span></div><div><span class="stat-value">{{ likedCount }}</span><span class="stat-label">YÊU THÍCH</span></div><div><span class="stat-value">{{ history.length }}</span><span class="stat-label">ĐÃ NGHE</span></div><div class="status-note"><i></i> Đồng bộ thư viện cá nhân</div></div>

    <section v-if="!onlyLiked && recommendations.length" class="discovery-panel" aria-labelledby="discovery-title"><div class="discovery-heading"><div><p class="eyebrow">PERSONAL ROTATION / 01</p><h2 id="discovery-title">Dành cho <em>bạn.</em></h2><p>LuNu chọn một vòng nghe dựa trên những gì bạn đã yêu thích và thường quay lại.</p></div><button class="discovery-play" type="button" @click="playRecommendation(recommendations[0])">▶ Phát mix</button></div><div class="recommendation-grid"><button v-for="(song, index) in recommendations" :key="song.id" class="recommendation-card" type="button" @click="playRecommendation(song)"><div class="recommendation-art"><img :src="song.cover || fallbackCover" :alt="song.title" loading="lazy" /><span>{{ String(index + 1).padStart(2, '0') }}</span></div><div><strong>{{ song.title }}</strong><small>{{ song.artist || 'Unknown artist' }}</small></div><i>▶</i></button></div></section>

    <div class="library-toolbar"><div class="section-heading"><p class="eyebrow">YOUR COLLECTION</p><h2>Thư viện âm nhạc</h2></div><label class="search-box"><span>⌕</span><input v-model="query" type="search" placeholder="Tìm bài hát hoặc nghệ sĩ..." aria-label="Tìm bài hát hoặc nghệ sĩ" /></label><select v-model="sortBy" aria-label="Sắp xếp thư viện"><option value="recent">Mới cập nhật</option><option value="title">Tên bài hát</option><option value="artist">Nghệ sĩ</option></select></div>

    <div v-if="loading" class="skeleton-grid"><div v-for="n in 6" :key="n" class="skeleton-card"><div></div><span></span><small></small></div></div>
    <div v-else-if="error" class="state-card error-state"><span>!</span><h3>Không thể tải thư viện</h3><p>{{ error }}</p><button class="ghost-btn" @click="$emit('retry')">Thử lại</button></div>
    <div v-else-if="!songs.length" class="state-card"><span>✦</span><h3>Thư viện đang chờ bản nhạc đầu tiên</h3><p>Hãy mở khu vực quản trị để thêm nhạc vào Cloudinary và Supabase.</p></div>
    <div v-else-if="!filteredSongs.length" class="state-card"><span>⌕</span><h3>Không tìm thấy kết quả</h3><p>Thử một từ khóa khác hoặc xóa bộ lọc tìm kiếm.</p></div>
    <div v-else class="songs-grid"><article v-for="(song, index) in filteredSongs" :key="song.id" class="song-card" :class="{ active: state.currentSong?.id === song.id }"><div class="cover-wrapper"><img :src="song.cover || fallbackCover" :alt="`Bìa ${song.title}`" class="song-cover" loading="lazy" /><div class="cover-shade"></div><button class="card-play" @click="play(song)" :aria-label="`Phát ${song.title}`">{{ state.currentSong?.id === song.id && state.isPlaying ? 'Ⅱ' : '▶' }}</button><span class="card-index">{{ String(index + 1).padStart(2, '0') }}</span></div><div class="song-info"><div class="song-topline"><h3 class="song-title">{{ song.title }}</h3><button class="like-btn" :class="{ liked: isLiked(song.id) }" @click="toggleLike(song)" :aria-label="isLiked(song.id) ? 'Bỏ yêu thích' : 'Thêm vào yêu thích'">{{ isLiked(song.id) ? '♥' : '♡' }}</button></div><p class="song-artist">{{ song.artist || 'Unknown artist' }}</p><div class="card-meta"><span>{{ song.album || 'SINGLE' }}</span><div class="card-actions"><button @click="addToQueue(song)">+ Hàng đợi</button><button @click.stop="playlistMenuSong = song">+ Playlist</button></div></div></div></article></div>

    <Teleport to="body"><div v-if="playlistMenuSong" class="playlist-picker-backdrop" @click.self="playlistMenuSong = null"><section class="playlist-picker glass-panel" role="dialog" aria-modal="true" aria-label="Thêm bài hát vào playlist"><header><div><p class="eyebrow">ADD TO COLLECTION</p><h2>Thêm vào playlist</h2><p>{{ playlistMenuSong.title }}</p></div><button type="button" class="picker-close" @click="playlistMenuSong = null">×</button></header><div v-if="playlists.length" class="playlist-picker-list"><button v-for="playlist in playlists" :key="playlist.id" type="button" :disabled="hasSong(playlist, playlistMenuSong.id)" @click="addSongToPlaylist(playlist)"><span>◒</span><span><strong>{{ playlist.name }}</strong><small>{{ hasSong(playlist, playlistMenuSong.id) ? 'Đã có trong playlist' : `${playlist.songIds.length} bài hát` }}</small></span><b>{{ hasSong(playlist, playlistMenuSong.id) ? '✓' : '+' }}</b></button></div><div v-else class="picker-empty"><p>Bạn chưa có playlist nào.</p><button type="button" @click="goToPlaylists">Tạo playlist đầu tiên →</button></div></section></div></Teleport>

    <section v-if="!onlyLiked && history.length" class="recent-section"><div class="section-heading"><p class="eyebrow">LISTENING HISTORY</p><h2>Nghe gần đây</h2></div><div class="recent-list"><button v-for="item in history.slice(0, 4)" :key="item.id" class="recent-item" @click="play(item.song)"><img :src="item.song.cover || fallbackCover" :alt="item.song.title" /><span><strong>{{ item.song.title }}</strong><small>{{ item.song.artist }}</small></span><b>▶</b></button></div></section>
  </section>
</template>

<script setup>
import { computed, ref } from 'vue';
import songs from '../data/songs';
import { useLibrary } from '../composables/useLibrary';
import { addToQueue, playSong, playerState } from '../store/playerState';
import { usePlaylists } from '../composables/usePlaylists';
import { currentView } from '../store/appState';

const props = defineProps({ songs: { type: Array, default: () => songs }, loading: Boolean, error: { type: String, default: '' }, onlyLiked: Boolean });
defineEmits(['retry']);
const query = ref('');
const sortBy = ref('recent');
const fallbackCover = '/images/ChoCiu.jpg';
const state = playerState;
const { isLiked, toggleLike: changeLike, history, likedCount, recordPlay } = useLibrary();
const { playlists, addSong, hasSong } = usePlaylists();
const playlistMenuSong = ref(null);
const normalize = (value) => String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const recommendationScore = (song) => { const artist = normalize(song.artist); const likedArtist = props.songs.some((item) => isLiked(item.id) && normalize(item.artist) === artist); const historyIndex = history.value.findIndex((item) => String(item.songId) === String(song.id)); const stable = String(song.id).split('').reduce((sum, char) => sum + char.charCodeAt(0), 0) % 17; return (isLiked(song.id) ? 50 : 0) + (likedArtist ? 25 : 0) + (historyIndex >= 0 ? 18 - historyIndex : 8) + stable / 100; };
const recommendations = computed(() => [...props.songs].sort((a, b) => recommendationScore(b) - recommendationScore(a)).slice(0, 5));
const playRecommendation = (song) => { play(song); };
const addSongToPlaylist = (playlist) => { if (!playlistMenuSong.value) return; addSong(playlist.id, playlistMenuSong.value.id); playlistMenuSong.value = null; };
const goToPlaylists = () => { playlistMenuSong.value = null; currentView.value = 'playlists'; };
const filteredSongs = computed(() => {
  const normalized = query.value.trim().toLowerCase();
  const list = props.songs.filter((song) => (!props.onlyLiked || isLiked(song.id)) && (!normalized || `${song.title} ${song.artist}`.toLowerCase().includes(normalized)));
  return [...list].sort((a, b) => sortBy.value === 'title' ? a.title.localeCompare(b.title) : sortBy.value === 'artist' ? (a.artist || '').localeCompare(b.artist || '') : 0);
});
const play = (song) => { const scopedSongs = props.onlyLiked ? filteredSongs.value : props.songs; playSong(song, scopedSongs); recordPlay(song); };
const playAll = () => { if (filteredSongs.value[0]) play(filteredSongs.value[0]); };
const toggleLike = (song) => changeLike(song);
</script>

